"""Flight availability and price search handlers."""
import json

from db import get_connection


def query_available(conn, origin, destination, flight_date, passengers):
    """Return flights with enough seats for the route and date."""
    return conn.execute(
        "SELECT id, flight_number, departure_time "
        "FROM flights "
        "WHERE origin = ? AND destination = ? AND flight_date = ? "
        "AND seats_available >= ? "
        "ORDER BY departure_time",
        (origin, destination, flight_date, passengers),
    ).fetchall()


def query_price(conn, flight_id):
    """Return the amount for a flight's price row, or None."""
    row = conn.execute(
        "SELECT amount_cents FROM prices WHERE flight_id = ?",
        (flight_id,),
    ).fetchone()
    return row["amount_cents"] if row else None


def search_flights(origin, destination, flight_date, passengers):
    """Return available flights with prices, in departure order."""
    conn = get_connection()
    try:
        available = query_available(conn, origin, destination, flight_date, passengers)
        results = []
        for flight in available:
            price = query_price(conn, flight["id"])
            if price is None:
                continue
            results.append({
                "flight_id": flight["id"],
                "flight_number": flight["flight_number"],
                "departure_time": flight["departure_time"],
                "price_cents": price,
            })
        return json.dumps(results)
    finally:
        conn.close()


def fetch_lowest_fare(origin, destination, flight_date):
    """Return the cheapest fare for a route and date, or None."""
    conn = get_connection()
    try:
        flights = query_available(conn, origin, destination, flight_date, 1)
        fares = []
        for flight in flights:
            price = query_price(conn, flight["id"])
            if price is not None:
                fares.append(price)
        return min(fares) if fares else None
    finally:
        conn.close()

"""Per-order totals for food delivery restaurants."""
import json

from db import get_connection


def fetch_order_items(conn, restaurant_id, day):
    """Return the day's item rows for one restaurant."""
    return conn.execute(
        "SELECT oi.order_id, oi.quantity, oi.unit_price_cents "
        "FROM order_items oi "
        "JOIN orders o ON o.id = oi.order_id "
        "WHERE o.restaurant_id = ? AND o.created_at LIKE ?",
        (restaurant_id, day + "%"),
    ).fetchall()


def compute_totals(rows):
    """Sum quantity * unit_price per order id."""
    totals = {}
    for row in rows:
        totals[row["order_id"]] = (
            totals.get(row["order_id"], 0)
            + row["quantity"] * row["unit_price_cents"]
        )
    return totals


def order_totals(restaurant_id, day):
    """Return each order id mapped to its total in cents as JSON."""
    conn = get_connection()
    try:
        rows = fetch_order_items(conn, restaurant_id, day)
        return json.dumps(compute_totals(rows))
    finally:
        conn.close()


def daily_revenue(restaurant_id, day):
    """Return total revenue in cents for a restaurant on a day."""
    conn = get_connection()
    try:
        rows = fetch_order_items(conn, restaurant_id, day)
        return sum(r["quantity"] * r["unit_price_cents"] for r in rows)
    finally:
        conn.close()

