            "ORDER BY posted_at DESC",
            ("%" + term + "%", "%" + term + "%", "%" + location + "%"),
        ).fetchall()
        jobs = [
            {"id": row[0], "title": row[1], "company": row[2], "location": row[3]}
            for row in rows
        ]
        return {"ok": True, "jobs": jobs}
    except sqlite3.Error as exc:
        return {"ok": False, "error": {"code": "search_failed", "message": str(exc)}}
    finally:
